'use strict';
// Keep native selects as the source of values, options, validation and form events.
(()=>{
 if(!HTMLElement.prototype.showPopover)return;
 const controls=new Map();let active=null,anchorRect=null,cursor=0,rows=[],search='',searchTimer;
 const popup=document.createElement('div');popup.className='shared-select-popup';popup.id='sharedSelectPopup';popup.setAttribute('role','listbox');popup.setAttribute('popover','manual');
 function close(){if(!active)return;if(popup.matches(':popover-open'))popup.hidePopover();popup.remove();active.button.setAttribute('aria-expanded','false');active.button.removeAttribute('aria-activedescendant');active=null;}
 function name(select){return select.getAttribute('aria-label')||[...select.labels||[]].map(l=>[...l.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('').trim()).join(' ')||'선택';}
 function sync(control){const {select,button}=control;button.textContent=select.selectedOptions[0]?.textContent||'선택하세요';button.disabled=select.disabled;button.hidden=select.hidden;button.setAttribute('aria-label',name(select)+': '+button.textContent);for(const attr of ['aria-describedby','aria-invalid']){if(select.hasAttribute(attr))button.setAttribute(attr,select.getAttribute(attr));else button.removeAttribute(attr);}if(select.disabled&&active===control)close();}
 function highlight(){rows.forEach((r,i)=>r.button.classList.toggle('is-highlighted',i===cursor));const row=rows[cursor];if(row){active.button.setAttribute('aria-activedescendant',row.button.id);row.button.scrollIntoView({block:'nearest'});}}
 function choose(index){const control=active;if(!control||control.select.options[index]?.disabled)return;const select=control.select;close();select.selectedIndex=index;select.dispatchEvent(new Event('input',{bubbles:true}));select.dispatchEvent(new Event('change',{bubbles:true}));if(control.button.isConnected){sync(control);control.button.focus({preventScroll:true});}}
 function open(control){close();sync(control);if(control.button.disabled)return;active=control;const {select,button}=control;popup.replaceChildren();rows=[];let group=null;
  [...select.options].forEach((option,index)=>{if(option.hidden||option.parentElement.hidden)return;const parent=option.closest('optgroup');if(parent&&parent!==group){const title=document.createElement('div');title.className='shared-select-group';title.textContent=parent.label;popup.append(title);}group=parent;const item=document.createElement('button');item.type='button';item.tabIndex=-1;item.id='sharedSelectOption'+index;item.className='shared-select-option';item.textContent=option.textContent;item.disabled=option.disabled||Boolean(parent?.disabled);item.setAttribute('role','option');item.setAttribute('aria-selected',String(index===select.selectedIndex));item.addEventListener('click',()=>choose(index));popup.append(item);if(!item.disabled)rows.push({button:item,index});});
  (button.closest('dialog')||document.body).append(popup);popup.showPopover();button.setAttribute('aria-expanded','true');popup.setAttribute('aria-label',name(select));const rect=button.getBoundingClientRect();anchorRect=rect;popup.style.width=Math.min(Math.max(rect.width,180),innerWidth-24)+'px';popup.style.maxHeight=Math.max(100,Math.min(320,Math.max(rect.top,innerHeight-rect.bottom)-16))+'px';const h=popup.getBoundingClientRect().height,w=popup.getBoundingClientRect().width;popup.style.left=Math.max(12,Math.min(rect.left,innerWidth-w-12))+'px';popup.style.top=Math.max(8,rect.bottom+h+4>innerHeight?rect.top-h-4:rect.bottom+4)+'px';cursor=Math.max(0,rows.findIndex(r=>r.index===select.selectedIndex));highlight();
 }
 function enhance(select){if(controls.has(select)||select.multiple||select.size>1||select.hidden||select.classList.contains('build-charm-select'))return;const button=document.createElement('button');button.type='button';button.className='shared-select-toggle';button.setAttribute('role','combobox');button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-controls',popup.id);button.setAttribute('aria-expanded','false');select.classList.add('shared-select-native');select.after(button);const control={select,button};controls.set(select,control);sync(control);
  button.addEventListener('click',e=>{e.preventDefault();active===control?close():open(control);});
  button.addEventListener('keydown',e=>{const k=e.key;if(k==='Tab'){close();return;}if(k==='Escape'){if(active){e.preventDefault();e.stopPropagation();close();}return;}if(['ArrowDown','ArrowUp','Home','End','Enter',' '].includes(k)){e.preventDefault();if(active!==control){open(control);return;}if(k==='Enter'||k===' '){if(rows[cursor])choose(rows[cursor].index);return;}cursor=k==='Home'?0:k==='End'?rows.length-1:Math.max(0,Math.min(rows.length-1,cursor+(k==='ArrowDown'?1:-1)));highlight();}else if(k.length===1&&!e.ctrlKey&&!e.metaKey){e.preventDefault();if(active!==control)open(control);clearTimeout(searchTimer);search+=k.toLocaleLowerCase('ko');const found=rows.findIndex(r=>r.button.textContent.trim().toLocaleLowerCase('ko').startsWith(search));if(found>=0){cursor=found;highlight();}searchTimer=setTimeout(()=>{search='';},700);}});
  select.addEventListener('invalid',e=>{e.preventDefault();button.focus();open(control);});select.focus=options=>button.focus(options);
 }
 function scan(root){if(root.matches?.('select'))enhance(root);root.querySelectorAll?.('select').forEach(enhance);}
 scan(document);
 const observer=new MutationObserver(records=>{const dirty=new Set();for(const r of records){if(r.type==='childList')for(const node of r.addedNodes)if(node.nodeType===1)scan(node);const select=r.target.closest?.('select')||r.target.parentElement?.closest('select');if(select){enhance(select);if(controls.has(select))dirty.add(controls.get(select));}}for(const c of dirty)sync(c);for(const [select,c]of controls)if(!select.isConnected){if(active===c)close();controls.delete(select);}});
 observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['disabled','selected','label','hidden','aria-label','aria-invalid']});
 const syncAll=()=>{for(const c of controls.values())sync(c);};for(const event of ['change','input','reset','page-enter','click','focusin'])document.addEventListener(event,()=>queueMicrotask(syncAll));
 document.addEventListener('pointerdown',e=>{if(active&&!popup.contains(e.target)&&e.target!==active.button)close();});document.addEventListener('focusin',e=>{if(active&&!popup.contains(e.target)&&e.target!==active.button)close();});document.addEventListener('scroll',e=>{if(active&&!popup.contains(e.target)){const rect=active.button.getBoundingClientRect();if(rect.top!==anchorRect.top||rect.left!==anchorRect.left)close();}},true);window.addEventListener('resize',close);document.addEventListener('close',close,true);
})();
